const cats=[['all','All agents'],['grow','Grow revenue'],['loss','Reduce losses'],['insights','Get insights'],['cash','Manage cash']];
function renderDrafts(ctx){
 const drafts=ctx.state.drafts||[];
 if(!drafts.length)return '';
 return `<section class="draft-section"><div class="section-head"><div><h2>Draft workflows</h2><p class="muted small">Saved locally in this demo workspace.</p></div>${button(icon('plus',14)+' New draft','studio-builder')}</div><div class="card flush">${drafts.map(d=>`<article class="my-agent-row draft-row"><div class="icon-tile blue">${icon('sparkles',22)}</div><div class="agent-copy"><div class="row wrap"><strong class="draft-name">${esc(d.name)}</strong>${badge('Draft','blue')}</div><p class="draft-task">${esc(d.task)}</p><div class="draft-trigger">${icon('clock',12)} ${esc(d.trigger)}</div></div><div class="row" style="gap:4px">${button(icon('x',14),'studio-draft-delete','ghost',`data-id="${esc(d.id)}" aria-label="Delete ${esc(d.name)} draft"`)}${button('Open draft '+icon('chevron-right',13),'studio-draft-open','secondary',`data-id="${esc(d.id)}"`)}</div></article>`).join('')}</div></section>`;
}
function showDraft(ctx,draft){
 ctx.drawer(`<div class="modal-head"><h2>${esc(draft.name)}</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close draft"')}</div>${badge('Draft saved','blue')}<div class="stack" style="margin-top:24px"><div class="card"><h3>When</h3><p class="muted">${esc(draft.trigger)}</p></div><div class="card"><h3>Task</h3><p class="muted">${esc(draft.task)}</p></div><div class="callout">${icon('shield',18)}<span>This draft uses synthetic payment data and runs in review-first mode.</span></div>${button('Preview a demo run','studio-run-draft','primary',`data-id="${esc(draft.id)}"`)}<a href="#/studio/mine" class="btn">View all saved drafts</a></div>`);
}
export function renderStudio(ctx,tab='home'){
 const tabs=`<nav class="tabs" aria-label="Agent Studio sections">${[['home','Explore'],['mine','My agents'],['connectors','Connectors']].map(([id,label])=>`<a href="#/studio/${id}" class="tab ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;
 return tabs+(tab==='mine'?renderMine(ctx):tab==='connectors'?renderConnectors(ctx):renderHome(ctx));
}
function renderHome(ctx){
 const slideIndex=ctx.ui.slide||0,query=(ctx.ui.agentSearch||'').toLowerCase(),cat=ctx.ui.category||'all';
 const list=agents.filter(a=>(cat==='all'||a.cat===cat)&&(a.name+' '+a.title).toLowerCase().includes(query));
 return `<section class="hero" aria-label="Featured agents" data-carousel><div class="hero-track" style="transform:translateX(-${slideIndex*100}%)">${slides.map((sl,i)=>{const a=agents.find(a=>a.id===sl.id);return `<article class="hero-slide" ${i!==slideIndex?'inert aria-hidden="true"':''}><div class="hero-copy">${badge(sl.kicker,a.tone)}<h1>${sl.title}</h1><p>${sl.sub}</p><div class="hero-cta"><span class="icon-tile ${a.tone}">${icon(a.icon,19)}</span><strong>${a.name}</strong><a class="btn btn-primary" href="#/agent/${a.id}">View agent ${icon('arrow-right',14)}</a></div></div><div class="hero-visual"><div class="glass-card"><div class="row"><span class="icon-tile ${a.tone}">${icon(a.icon,17)}</span><div><strong>${sl.card}</strong><small>${sl.location}</small></div>${badge(sl.tag,'green')}</div><div class="mini-progress"><span style="width:${sl.bar}%"></span></div><div class="signal-chips">${sl.chips.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="mini-quote"><span>${sl.footer}</span><b>${sl.value}</b></div></div></div></article>`}).join('')}</div><div class="hero-controls">${slides.map((_,i)=>`<button class="hero-dot ${i===slideIndex?'active':''}" data-action="studio-slide" data-index="${i}" aria-label="Show featured agent ${i+1}" aria-pressed="${i===slideIndex}"></button>`).join('')}</div><div class="hero-arrows"><button data-action="studio-slide-prev" aria-label="Previous featured agent">${icon('chevron-left',14)}</button><button data-action="studio-slide-next" aria-label="Next featured agent">${icon('chevron-right',14)}</button></div></section>
 <div class="catalog-head"><div><h2>Explore agents</h2><p>A little less busywork. A lot more business.</p></div><label class="search-field">${icon('search',15)}<input aria-label="Search agents" data-action="studio-search" placeholder="Search agents" value="${esc(ctx.ui.agentSearch||'')}"></label></div>
 <div class="chips" aria-label="Filter agents by purpose">${cats.map(([id,label])=>`<button class="chip ${cat===id?'active':''}" data-action="studio-category" data-category="${id}" aria-pressed="${cat===id}">${label}</button>`).join('')}</div>
 ${list.length?`<div class="agent-grid">${list.map(a=>`<a href="#/agent/${a.id}" class="agent-card"><div class="row"><span style="color:${a.color}">${icon(a.icon,21)}</span><span class="agent-name">${a.name}</span>${a.id==='business'?badge('New','green'):''}</div><h3>${a.title}</h3><div class="integrations">${a.connections.map((name,i)=>`<span title="${i===0?'Razorpay Payments':name==='shopping-bag'?'Shopify':name==='message'?'WhatsApp':name==='mail'?'Email':name==='truck'?'Shiprocket':'Voice'}" style="color:${i===0?'#3476d9':name==='shopping-bag'||name==='message'?'#389c65':'#8490a0'}">${icon(name,16)}</span>`).join('')}<span class="open-arrow">${icon('arrow-right',15)}</span></div></a>`).join('')}<button class="agent-card build-card" data-action="studio-builder"><div class="row">${icon('plus',21)}<span class="agent-name">Build your own</span></div><h3>Create custom automations for your workflows</h3><p>Try the builder ${icon('arrow-right',12)}</p></button></div>`:empty('No agents found','Try a different name or choose another category.')}`;
}
function renderMine(ctx){
 const ids=[...(ctx.state.installed?['business']:[]),'dispute','subs','cart',...(ctx.state.extraAgents||[])];
 return `<div class="page-title"><div><h1>My agents</h1><p>Manage your active AI workforce.</p></div>${button(icon('bell',15)+' Notification preferences','studio-notifications')}</div>
 ${!ctx.state.installed?`<div class="callout" style="margin-bottom:20px">${icon('store',19)}<span>${ctx.state.installDraft?'Your B2B setup is saved. Continue where you left off.':'Your B2B Customer Agent is ready to set up.'}</span><a href="#/agent/business" class="btn btn-primary" style="margin-left:auto">${ctx.state.installDraft?'Resume setup':'Explore agent'} ${icon('arrow-right',13)}</a></div>`:''}
 <div class="card flush">${ids.map(id=>{const a=agents.find(a=>a.id===id);if(!a)return '';const paused=id==='business'?ctx.state.paused:!!ctx.state.agentPaused?.[id];return `<div class="my-agent-row"><div class="icon-tile ${a.tone}">${icon(a.icon,23)}</div><div class="agent-copy"><div class="row wrap" style="gap:9px"><strong>${a.name}</strong><span class="healthy" style="color:${paused?'#a66a13':''}">${icon(paused?'pause':'check-circle',11)} ${paused?'PAUSED':'HEALTHY'}</span>${id==='business'&&ctx.state.pending.length?badge(ctx.state.pending.length+' review items','orange'):''}</div><p>Last action: ${id==='business'?'Advance of ₹15,246 received from Urban Nest Co-living (6 min ago)':id==='dispute'?'Responded to dispute #DIS-4521 with delivery proof (2 hours ago)':id==='subs'?'Reminder sent for a failed renewal · ₹1,499 at risk (12 min ago)':'Customer paid ₹2,980 after a helpful follow-up (45 min ago)'}</p></div><div class="row" style="gap:4px">${button(icon(paused?'play':'pause',15),'studio-pause','ghost',`data-id="${id}" aria-label="${paused?'Resume':'Pause'} ${a.name}"`)}<a href="#/agent/${id}${id==='business'?'/settings':''}" class="btn btn-ghost" aria-label="${a.name} settings">${icon('settings',15)}</a><a href="#/agent/${id}/${id==='business'&&ctx.state.pending.length?'approvals':'dashboard'}" class="btn">View details ${icon('chevron-right',13)}</a></div></div>`}).join('')}</div>
 <div class="callout notice-banner">${icon('info',14)}<span>Demo workspace · Synthetic activity shown as of 12 October 2026. All connections and actions are simulated.</span></div>
 ${renderDrafts(ctx)}<section style="margin-top:26px"><div class="section-head"><h2>Recent activity</h2><a href="#/agent/business/activity" class="small">View all ${icon('arrow-right',12)}</a></div>${[...(ctx.state.extraActivity||[]).slice(0,2).map(x=>({title:x.title+' · '+(x.buyer||'All buyers'),agent:'B2B Customer Agent',icon:'check-circle',tone:'green',time:'Just now'})),...(ctx.state.installed?[{title:'Advance received from Urban Nest Co-living · ₹15,246',agent:'B2B Customer Agent',icon:'rupee',tone:'green',time:'6 minutes ago'},{title:'Quote drafted for Sai Krupa PG · ₹21,042',agent:'B2B Customer Agent',icon:'clock',tone:'orange',time:'3 hours ago'}]:[]),{title:'Reminder sent for a failed renewal · ₹1,499 at risk',agent:'Subscription Recovery',icon:'refresh',tone:'purple',time:'12 minutes ago'},{title:'Responded to dispute #DIS-4521 with delivery proof',agent:'Dispute Responder',icon:'scales',tone:'red',time:'2 hours ago'}].map(r=>`<div class="recent-row"><div class="icon-tile ${r.tone}">${icon(r.icon,15)}</div><div><span class="small muted" style="font-size:10px">${esc(r.agent)}</span><div><strong>${esc(r.title)}</strong></div><p>${esc(r.time)}</p></div></div>`).join('')}</section>`;
}
function renderConnectors(ctx){return `<div class="page-title"><div><h1>Connectors</h1><p>The data and tools your agents work with.</p></div>${badge('Demo workspace','blue')}</div><div class="callout" style="margin-bottom:20px">${icon('info',17)}<span>Explore setup with simulated connections. This prototype never connects to an external account.</span></div><div class="grid-3">${connectors.map(c=>{const status=connectorStatus(ctx.state,c.id),available=['Available','Disconnected','Expired'].includes(status),expiring=status==='Expires in 3 days';return `<article class="card connector-card"><div class="row"><div class="icon-tile ${c.tone||''}">${icon(c.icon,22)}</div><div><h3>${c.name}</h3><div class="connector-status" style="margin-top:4px"><span class="status-dot" style="background:${available?'#a9b4c2':expiring?'#e5a331':''}"></span>${esc(status)}</div></div></div><p>${c.use}</p>${button(available?'Try demo connection':expiring?'Reconnect demo':'Manage','studio-connector',available?'primary':'secondary',`data-id="${c.id}"`)}</article>`}).join('')}</div><div style="margin-top:20px">${button(icon('plus',14)+' Request a connector','studio-request','ghost')}</div>`;}
export function handleStudio(action,el,ctx){
 if(action==='studio-slide'||action==='studio-slide-prev'||action==='studio-slide-next'){ctx.ui.slide=action==='studio-slide'?Number(el.dataset.index):((ctx.ui.slide||0)+(action.endsWith('prev')?-1:1)+4)%4;changeSlide(ctx);}
 if(action==='studio-search'){ctx.ui.agentSearch=el.value;ctx.rerender();}
 if(action==='studio-category'){ctx.ui.category=el.dataset.category;ctx.rerender();}
 if(action==='studio-pause'){if(el.dataset.id==='business'){if(ctx.state.paused)ctx.resume();else ctx.pause();}else{const id=el.dataset.id;ctx.update({agentPaused:{...ctx.state.agentPaused,[id]:!ctx.state.agentPaused?.[id]}});ctx.toast((ctx.state.agentPaused[id]?'Paused ':'Resumed ')+agents.find(a=>a.id===id).name);}}
 if(action==='studio-connector'){const c=connectors.find(c=>c.id===el.dataset.id);ctx.modal(`<div class="modal-body"><div class="modal-head"><div class="row"><span class="icon-tile ${c.tone||''}">${icon(c.icon,22)}</span><h2>${c.name}</h2></div>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><p class="muted">${c.use}</p><div class="callout" style="margin-top:20px">${icon('info',18)}<span>This is a simulated connection. No credentials or external account access are required.</span></div><div class="card" style="margin-top:20px"><div class="row between"><span>Status</span>${badge(connectorStatus(ctx.state,c.id),'blue')}</div><div class="row between" style="margin-top:12px"><span>Workspace</span><strong>Kesar Linen</strong></div></div><div class="modal-actions">${button('Close','overlay-close')}${!['payments','checkout'].includes(c.id)&&!['Available','Disconnected'].includes(connectorStatus(ctx.state,c.id))?button('Disconnect','studio-disconnect','ghost',`data-id="${c.id}"`):''}${button(c.status==='Built in'||c.status==='Pre-enabled'?'Verify demo connection':'Confirm demo connection','studio-connect-confirm','primary',`data-id="${c.id}"`)}</div></div>`);}
 if(action==='studio-disconnect'){ctx.connect(el.dataset.id,'Disconnected');ctx.closeOverlay();ctx.toast('Demo connection disconnected');}
 if(action==='studio-connect-confirm'){ctx.connect(el.dataset.id);ctx.closeOverlay();ctx.toast('Demo connection verified. No external accounts were accessed.');}
 if(action==='studio-notifications'){ctx.modal(`<div class="modal-body"><div class="modal-head"><h2>Notification preferences</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><p class="muted">Choose which updates appear in this demo workspace.</p><div class="stack" style="margin-top:20px">${[['approvals','Approvals that need my attention'],['outcomes','Orders and payments received'],['weekly','Weekly performance summary']].map(([id,text])=>`<label class="row"><input type="checkbox" data-action="studio-notification-toggle" data-key="${id}" ${ctx.state.notifications?.[id]!==false?'checked':''}>${text}</label>`).join('')}</div><div class="modal-actions">${button('Done','overlay-close','primary')}</div></div>`);}
 if(action==='studio-notification-toggle'){ctx.update({notifications:{...ctx.state.notifications,[el.dataset.key]:el.checked}});}
 if(action==='studio-builder'){ctx.modal(`<div class="modal-body"><div class="modal-head"><h2>Build your own agent</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><p class="muted">Create a draft workflow with synthetic data.</p><div class="stack" style="margin-top:20px"><label class="field"><span class="field-label">Agent name</span><input id="builder-name" placeholder="e.g. Weekly sales assistant" maxlength="60"></label><label class="field"><span class="field-label">What should it do?</span><textarea id="builder-task" placeholder="Summarise weekly sales and highlight returning buyers" maxlength="600"></textarea></label><label class="field"><span class="field-label">Trigger</span><select id="builder-trigger"><option>Every Monday at 09:00</option><option>When an order is received</option><option>When a payment fails</option></select></label></div><div class="modal-actions">${button('Cancel','overlay-close')}${button('Create draft','studio-create-draft','primary')}</div></div>`);}
 if(action==='studio-create-draft'){const name=document.getElementById('builder-name').value.trim(),task=document.getElementById('builder-task').value.trim();if(!name||!task){ctx.toast('Add an agent name and its task to create a draft.');return;}const draft={id:Date.now().toString(),name,task,trigger:document.getElementById('builder-trigger').value};ctx.update({drafts:[...(ctx.state.drafts||[]),draft]});ctx.closeOverlay();showDraft(ctx,draft);ctx.toast('Draft saved. Find it under My agents.');}
 if(action==='studio-draft-open'){const draft=(ctx.state.drafts||[]).find(d=>d.id===el.dataset.id);if(draft)showDraft(ctx,draft);}
 if(action==='studio-draft-delete'){const draft=(ctx.state.drafts||[]).find(d=>d.id===el.dataset.id);if(draft)ctx.modal(`<div class="modal-body"><div class="modal-head"><h2>Delete this draft?</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><p>Remove <strong>${esc(draft.name)}</strong> from your saved demo workflows.</p><div class="modal-actions">${button('Keep draft','overlay-close')}${button('Delete draft','studio-draft-delete-confirm','danger',`data-id="${esc(draft.id)}"`)}</div></div>`);}
 if(action==='studio-draft-delete-confirm'){ctx.update({drafts:(ctx.state.drafts||[]).filter(d=>d.id!==el.dataset.id)});ctx.closeOverlay();ctx.toast('Demo draft deleted.');}
 if(action==='studio-run-draft'){const stats=performance('since');ctx.toast(`Demo run complete: ${stats.orders} orders, ${money(stats.revenue)} revenue, and ${stats.repeat} returning business buyers.`);ctx.closeOverlay();}
 if(action==='studio-request'){ctx.modal(`<div class="modal-body"><div class="modal-head"><h2>Request a connector</h2>${button(icon('x',17),'overlay-close','ghost','aria-label="Close"')}</div><label class="field"><span>Which tool would help your business?</span><input id="connector-request" maxlength="80" placeholder="e.g. FreshBooks"></label><div class="modal-actions">${button('Save request in demo','studio-save-request','primary')}</div></div>`);}
 if(action==='studio-save-request'){const name=document.getElementById('connector-request').value.trim();if(!name){ctx.toast('Enter a connector name.');return;}ctx.update({requests:[...(ctx.state.requests||[]),name]});ctx.closeOverlay();ctx.toast('Saved your demo request for '+name+'.');}
}
export function changeSlide(ctx){const i=ctx.ui.slide||0;document.querySelector('.hero-track')?.style.setProperty('transform',`translateX(-${i*100}%)`);document.querySelectorAll('.hero-slide').forEach((el,n)=>{el.inert=n!==i;el.setAttribute('aria-hidden',String(n!==i));});document.querySelectorAll('.hero-dot').forEach((el,n)=>{el.classList.toggle('active',n===i);el.setAttribute('aria-pressed',String(n===i));});}
